     1	package hotel.reservations;
     2	
     3	import hotel.rooms.Room;
     4	import java.math.BigDecimal;
     5	import java.math.RoundingMode;
     6	import java.time.LocalDate;
     7	import java.time.Month;
     8	import java.util.List;
     9	
    10	/**
    11	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
    12	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
    13	 * (half-even) at every step.
    14	 */
    15	public final class PriceCalculator {
    16	
    17	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.25");
    18	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    19	
    20	    /** Easter week, from Palm Sunday to Easter Sunday (both nights included). */
    21	    private static final List<DateRange> EASTER_WEEKS = List.of(
    22	            new DateRange(LocalDate.of(2027, 3, 21), LocalDate.of(2027, 3, 28)),
    23	            new DateRange(LocalDate.of(2028, 4, 9), LocalDate.of(2028, 4, 16)));
    24	
    25	    private record DateRange(LocalDate first, LocalDate last) {
    26	        boolean contains(LocalDate date) {
    27	            return !date.isBefore(first) && !date.isAfter(last);
    28	        }
    29	    }
    30	
    31	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
    32	        int nights = 0;
    33	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    34	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    35	            subtotal = subtotal.add(nightPrice(room, night));
    36	            nights++;
    37	        }
    38	        BigDecimal discount = switch (ratePlan) {
    39	            case STANDARD -> cents(BigDecimal.ZERO);
    40	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
    41	        };
    42	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
    43	    }
    44	
    45	    BigDecimal nightPrice(Room room, LocalDate night) {
    46	        BigDecimal nightlyRate = room.nightlyRate();
    47	        if (isHighSeason(night)) {
    48	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
    49	        }
    50	        return cents(nightlyRate);
    51	    }
    52	
    53	    /** High season: from December 15 to the end of February, the whole of July, and Easter week. */
    54	    static boolean isHighSeason(LocalDate date) {
    55	        Month month = date.getMonth();
    56	        return month == Month.JANUARY
    57	                || month == Month.FEBRUARY
    58	                || month == Month.JULY
    59	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15)
    60	                || EASTER_WEEKS.stream().anyMatch(week -> week.contains(date));
    61	    }
    62	
    63	    static BigDecimal cents(BigDecimal value) {
    64	        return value.setScale(2, RoundingMode.HALF_EVEN);
    65	    }
    66	}
